files.src/pricing.py:
"""Prices for the shop."""


def apply_discount(price: float, percent: float) -> float:
    return price - price * percent / 100


def with_tax(price: float, rate: float = 0.05) -> float:
    return round(price * (1 + rate), 2)

files.src/api.py:
"""Public API used by partners. Signatures are frozen."""
from src.pricing import apply_discount, with_tax


def quote(price: float, percent: float = 0) -> float:
    return with_tax(apply_discount(price, percent))

